<?php require_once 'php/db.php'; header('Content-Type: text/plain');$tables = ['areas', 'cursos', 'carga_academica', 'personal', 'usuarios', 'roles', 'docentes', 'materias', 'asignaturas', 'intensidad_horaria', 'grados', 'especjalidades'];foreach ($tables as $t) { try { $stmt = $db->query("SHOW CREATE TABLE `$t`"); $res = $stmt->fetch(); if ($res) { echo "--- TABLE: $t ---\\n" . $res[1] . "\\n\\n"; } } catch (Exception $e) { echo "--- TABLE: $t (NOT FOUND OR ERROR: " . $e->getMessage() . ") ---\\n\\n"; } }
